    /// then assign the array back to `toolCalls`.
    #[wasm_bindgen(getter, js_name = "toolCalls")]
    pub fn tool_calls(&self) -> Option<js_sys::Array> {
        self.tool_calls.as_ref().map(|items| {
            let arr = js_sys::Array::new();
            for item in items {
                arr.push(&JsValue::from(item.clone()));
            }
            arr
        })
    }

    /// Takes ownership of every element in `toolCalls`.
