/// Opaque WASM handle for [`liter_llm::LiterLlmError`] that exposes introspection methods.
#[wasm_bindgen]
pub struct WasmLiterLlmError {
    pub(crate) inner: liter_llm::LiterLlmError,
}

#[wasm_bindgen]
impl WasmLiterLlmError {
    /// HTTP status code for this error variant.
    #[wasm_bindgen(js_name = "statusCode")]
    pub fn status_code(&self) -> u16 {
        self.inner.status_code()
    }

    /// `retry_after` in whole milliseconds (undefined when absent).
    #[wasm_bindgen(js_name = "retryAfter")]
    pub fn retry_after(&self) -> Option<u64> {
        self.inner.retry_after().map(|d| d.as_millis() as u64)
    }

    /// Returns `true` if the error is transient and a retry may succeed.
    #[wasm_bindgen(js_name = "isTransient")]
    pub fn is_transient(&self) -> bool {
        self.inner.is_transient()
    }

    /// Returns a machine-readable error category string.
    #[wasm_bindgen(js_name = "errorType")]
    pub fn error_type(&self) -> String {
        self.inner.error_type().to_string()
    }
}
